package com.bananalab.lite;
import android.content.*;import android.os.*;import java.io.*;import java.util.concurrent.*;
final class JavaTrial{
 static Bundle run(final Context c,final File jar,final String expression)throws Exception{return request(c,jar,expression,"curve",257);}
 static Bundle text(Context c,File jar,String plan,int samples)throws Exception{return request(c,jar,plan,"text",samples);}
 static Bundle request(final Context c,final File jar,final String expression,final String kind,final int samples)throws Exception{if(Looper.myLooper()==Looper.getMainLooper())throw new IOException("La prueba debe ejecutarse fuera del hilo de pantalla.");final CountDownLatch done=new CountDownLatch(1);final Bundle[] result={null};HandlerThread thread=new HandlerThread("banana-java-trial-response");thread.start();final Messenger reply=new Messenger(new Handler(thread.getLooper()){@Override public void handleMessage(Message message){result[0]=message.getData();done.countDown();}});ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName name,IBinder binder){try{Message m=Message.obtain();Bundle b=new Bundle();b.putString("jar",jar.getAbsolutePath());b.putString("expression",expression);b.putString("kind",kind);m.setData(b);m.replyTo=reply;new Messenger(binder).send(m);}catch(Exception e){done.countDown();}}public void onServiceDisconnected(ComponentName name){done.countDown();}};boolean bound=false;try{bound=c.bindService(new Intent(c,JavaTrialService.class),connection,Context.BIND_AUTO_CREATE);if(!bound)throw new IOException("No pude iniciar el proceso de prueba.");if(!done.await(20,TimeUnit.SECONDS))throw new IOException("La prueba superó20 segundos; no activé el candidato.");Bundle b=result[0];if(b==null||!b.getBoolean("ok"))throw new IOException(b==null?"Se interrumpió el proceso de prueba.":b.getString("error"));if(b.getInt("pid")==android.os.Process.myPid()||b.getInt("samples")!=samples)throw new IOException("La prueba no ocurrió en el proceso separado.");return b;}finally{if(bound)c.unbindService(connection);thread.quitSafely();}}
}
